class Solution {
    public String smallestGoodBase(String n) {
        long num = Long.parseLong(n);
        int maxDigits = 64 - Long.numberOfLeadingZeros(num);
        for (int digits = maxDigits; digits >= 3; digits--) {
            long lo = 2;
            long hi = (long) Math.pow(num, 1.0 / (digits - 1)) + 2;
            while (lo <= hi) {
                long base = lo + (hi - lo) / 2;
                int cmp = compareGeometricSum(base, digits, num);
                if (cmp == 0) return String.valueOf(base);
                if (cmp < 0) lo = base + 1;
                else hi = base - 1;
            }
        }
        return String.valueOf(num - 1);
    }

    private int compareGeometricSum(long base, int digits, long limit) {
        long sum = 1;
        long term = 1;
        for (int i = 1; i < digits; i++) {
            if (term > (limit - sum) / base) return 1;
            term *= base;
            sum += term;
        }
        return Long.compare(sum, limit);
    }
}

class Solution {
    public String smallestGoodBase(String n) {
        long num = Long.parseLong(n);
        int maxDigits = 64 - Long.numberOfLeadingZeros(num);
        for (int digits = maxDigits; digits >= 3; digits--) {
            long root = integerNthRoot(num, digits - 1);
            for (long base = Math.max(2, root - 2); base <= root + 2; base++) {
                if (compareGeometricSum(base, digits, num) == 0) return String.valueOf(base);
            }
        }
        return String.valueOf(num - 1);
    }

    private long integerNthRoot(long value, int power) {
        long lo = 2;
        long hi = (long) Math.sqrt(value) + 1;
        long answer = 1;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            int cmp = comparePower(mid, power, value);
            if (cmp <= 0) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer;
    }

    private int comparePower(long base, int power, long value) {
        long product = 1;
        for (int i = 0; i < power; i++) {
            if (product > value / base) return 1;
            product *= base;
        }
        return Long.compare(product, value);
    }

    private int compareGeometricSum(long base, int digits, long limit) {
        long sum = 1;
        long term = 1;
        for (int i = 1; i < digits; i++) {
            if (term > (limit - sum) / base) return 1;
            term *= base;
            sum += term;
        }
        return Long.compare(sum, limit);
    }
}

