import java.math.BigInteger;

class Solution {
    public String smallestGoodBase(String n) {
        long value = Long.parseLong(n);
        BigInteger target = new BigInteger(n);
        int maxDigits = 64 - Long.numberOfLeadingZeros(value);
        for (int digits = maxDigits; digits >= 3; digits--) {
            long lo = 2;
            long hi = (long) Math.pow(value, 1.0 / (digits - 1)) + 2;
            while (lo <= hi) {
                long base = lo + (hi - lo) / 2;
                int cmp = geometricSum(base, digits, target).compareTo(target);
                if (cmp == 0) return String.valueOf(base);
                if (cmp < 0) lo = base + 1;
                else hi = base - 1;
            }
        }
        return String.valueOf(value - 1);
    }

    private BigInteger geometricSum(long base, int digits, BigInteger limit) {
        BigInteger b = BigInteger.valueOf(base);
        BigInteger term = BigInteger.ONE;
        BigInteger sum = BigInteger.ONE;
        for (int i = 1; i < digits; i++) {
            term = term.multiply(b);
            sum = sum.add(term);
            if (sum.compareTo(limit) > 0) return sum;
        }
        return sum;
    }
}

class Solution {
    public String smallestGoodBase(String n) {
        long target = Long.parseLong(n);
        int maxDigits = 64 - Long.numberOfLeadingZeros(target);
        for (int digits = maxDigits; digits >= 3; digits--) {
            long left = 2;
            long right = maxPossibleBase(target, digits);
            while (left <= right) {
                long mid = left + (right - left) / 2;
                int cmp = compareRepunit(mid, digits, target);
                if (cmp == 0) return String.valueOf(mid);
                if (cmp < 0) left = mid + 1;
                else right = mid - 1;
            }
        }
        return String.valueOf(target - 1);
    }

    private long maxPossibleBase(long target, int digits) {
        long right = 2;
        while (right <= target / 2 && compareRepunit(right, digits, target) <= 0) {
            right *= 2;
        }
        return Math.min(right, target - 1);
    }

    private int compareRepunit(long base, int digits, long target) {
        long value = 1;
        for (int i = 1; i < digits; i++) {
            if (value > (target - 1) / base) return 1;
            value = value * base + 1;
        }
        return Long.compare(value, target);
    }
}
